import classes from './EventItem.module.css';

function EventItem({ event }) {
  // 1. Guard Clause: If event data is missing (undefined/null), 
  // stop here and return a fallback to prevent the app from crashing.
  if (!event) {
    return <p className={classes.fallback}>No event details found.</p>;
  }

  function startDeleteHandler() {
    // ...
  }

  return (
    <article className={classes.event}>
      {/* 2. Optional Chaining: event?.image acts as a secondary safety check */}
      <img src={event?.image} alt={event?.title} />
      <h1>{event?.title}</h1>
      <time>{event?.date}</time>
      <p>{event?.description}</p>
      <menu className={classes.actions}>
        <a href="edit">Edit</a>
        <button onClick={startDeleteHandler}>Delete</button>
      </menu>
    </article>
  );
}

export default EventItem;
